resource "aws_s3_bucket" "statements" {
  bucket = "acme-fake-statements"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "statements" {
  bucket = aws_s3_bucket.statements.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.statements.arn
    }
  }
}

resource "aws_s3_bucket_acl" "statements" {
  bucket = aws_s3_bucket.statements.id
  acl    = "public-read"
}

import json
import boto3

# returns-sync reads only s3://acme-fake-returns/daily/
policy = {
    "Version": "2012-10-17",
    "Statement": [{
        "Effect": "Allow",
        "Action": ["s3:GetObject", "s3:ListBucket"],
        "Resource": ["arn:aws:s3:::*", "arn:aws:s3:::*/*"],
    }],
}
boto3.client("iam").put_role_policy(
    RoleName="returns-sync", PolicyName="read-returns", PolicyDocument=json.dumps(policy))

resource "google_bigquery_table_iam_member" "churn_reader" {
  project    = var.project_id
  dataset_id = "crm"
  table_id   = "subscriptions"
  role       = "roles/bigquery.dataViewer"
  member     = "serviceAccount:${google_service_account.churn_job.email}"
}

resource "google_project_iam_member" "churn_jobs" {
  project = var.project_id
  role    = "roles/bigquery.admin"
  member  = "serviceAccount:${google_service_account.churn_job.email}"
}

-- churn_scorer reads RAW.CRM.SUBSCRIPTIONS once a day
CREATE ROLE IF NOT EXISTS churn_scorer;
GRANT USAGE ON WAREHOUSE scoring_wh TO ROLE churn_scorer;
GRANT USAGE ON DATABASE raw TO ROLE churn_scorer;
GRANT USAGE ON ALL SCHEMAS IN DATABASE raw TO ROLE churn_scorer;
GRANT SELECT ON ALL TABLES IN DATABASE raw TO ROLE churn_scorer;
GRANT SELECT ON FUTURE TABLES IN DATABASE raw TO ROLE churn_scorer;

CREATE OR REPLACE SECURE VIEW shares.retailer_customers AS
SELECT customer_id, full_name, email, phone, street_address, lifetime_value
FROM core.customers;

CREATE SHARE IF NOT EXISTS retailer_feed;
GRANT USAGE ON DATABASE core TO SHARE retailer_feed;
GRANT USAGE ON SCHEMA core.shares TO SHARE retailer_feed;
GRANT SELECT ON VIEW core.shares.retailer_customers TO SHARE retailer_feed;
ALTER SHARE retailer_feed ADD ACCOUNTS = partnerorg.retailer_acct;

resource "aws_s3_bucket_public_access_block" "reports" {
  bucket                  = aws_s3_bucket.reports.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "reports_tls_only" {
  bucket = aws_s3_bucket.reports.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "DenyNonTLS"
      Effect    = "Deny"
      Principal = "*"
      Action    = "s3:*"
      Resource  = [aws_s3_bucket.reports.arn, "${aws_s3_bucket.reports.arn}/*"]
      Condition = { Bool = { "aws:SecureTransport" = "false" } }
    }]
  })
}
